import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { useAuthStore } from './store/authStore';
import { SignalRProvider } from './context/SignalRContext';
import { VoterDashboard } from './pages/VoterDashboard';
import { PermissionGate } from './components/PermissionGate';

const App: React.FC = () => {
    const { token } = useAuthStore();

    if (!token) {
        // Simplifying: In real app, render Login page
        return <div>Please Login (Mock Login implementation pending)</div>;
    }

    return (
        <BrowserRouter>
            <SignalRProvider>
                <div className="min-h-screen bg-gray-100 text-gray-900 font-sans">
                    <Routes>
                        <Route path="/voter" element={
                            <PermissionGate permission="Permissions.CanViewDashboard">
                                <VoterDashboard />
                            </PermissionGate>
                        } />
                        {/* Add other protected routes */}
                        <Route path="*" element={<Navigate to="/voter" />} />
                    </Routes>
                </div>
            </SignalRProvider>
        </BrowserRouter>
    );
};

export default App;
